mapper.select:
select msg_id, partition_time, msg_tp, sttlm_dt, bat_id, biz_tp, biz_kind, trans_tp, send_pty_id, send_sys_id, recv_pty_id, recv_sys_id, dbtr_pty_id, dbtr_sys_id, dbtr_id, cbtr_pty_id, cbtr_sys_id, cbtr_id, currency, sttlm_amt, cdt_dbt_ind, biz_sts, biz_prc_cd, biz_prc_inf, biz_dt, biz_desc_inf, clr_flag, clr_prod, gmt_create, gmt_modified from settlement_prod where sttlm_dt = #{currentSystemDate,jdbcType=CHAR} and biz_sts in('PR11','PR06','PR02','PR12') and (UNIX_TIMESTAMP(now(3))-UNIX_TIMESTAMP(gmt_create) >= 15)
and msg_id > #{msgId,jdbcType=CHAR}
order by msg_id asc limit 100

